cmd:
mkdir -p /etc/nginx/sites-available
cat > /etc/nginx/sites-available/git-project <<'EOF'
server {
    listen 8443 ssl;
    server_name _;

    ssl_certificate     /etc/nginx/ssl/server.crt;
    ssl_certificate_key /etc/nginx/ssl/server.key;

    root /var/www/main;

    location / {
        try_files $uri $uri/ =404;
    }

    location /dev/ {
        alias /var/www/dev/;
        try_files $uri $uri/ =404;
    }
}
EOF
ln -sf /etc/nginx/sites-available/git-project /etc/nginx/sites-enabled/git-project
rm -f /etc/nginx/sites-enabled/default
mkdir -p /etc/nginx/ssl
openssl req -x509 -newkey rsa:2048 -keyout /etc/nginx/ssl/server.key -out /etc/nginx/ssl/server.crt -days 3650 -nodes -subj "/CN=localhost" 2>/dev/null
echo "Nginx config + SSL cert created"
